<?php namespace App\Jobs; use App\Contracts\SmsProvider; use App\Models\Booking; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Throwable; class SendTicketSmsJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=5; public array $backoff=[10,30,90,300,600]; public int $timeout=30; public function __construct(public int $bookingId){} public function handle(SmsProvider $sms):void{$b=Booking::with('user')->findOrFail($this->bookingId);if($b->status->value!=='paid'||!$b->user->phone)return;$key='ticket-sms-'.$b->id;cache()->lock('lock:'.$key,120)->block(10,function()use($b,$sms,$key){if(cache()->has('sent:'.$key))return;$sms->send($b->user->phone,'تم تأكيد حجزك رقم '.$b->id,$key);cache()->put('sent:'.$key,true,60*60*24*30);});} public function failed(?Throwable $e):void{logger()->critical('Ticket SMS permanently failed',['booking_id'=>$this->bookingId,'error'=>$e?->getMessage()]);}}
